type operationScopeRequest struct {
	Project string `json:"project,omitempty"`
	Sprint  string `json:"sprint,omitempty"`
	Study   string `json:"study,omitempty"`
}

type operationOptionsRequest struct {
	Stage             string   `json:"stage,omitempty"`
	ToStage           string   `json:"to_stage,omitempty"`
	Task              string   `json:"task,omitempty"`
	Shard             string   `json:"shard,omitempty"`
	Model             string   `json:"model,omitempty"`
	Action            string   `json:"action,omitempty"`
	DryRun            bool     `json:"dry_run,omitempty"`
	Resume            bool     `json:"resume,omitempty"`
	Level             string   `json:"level,omitempty"`
	Suite             string   `json:"suite,omitempty"`
	Test              string   `json:"test,omitempty"`
	Timeout           string   `json:"timeout,omitempty"`
	ForceReview       bool     `json:"force_review,omitempty"`
	RestartReview     bool     `json:"restart_review,omitempty"`
	OverrideRationale string   `json:"override_rationale,omitempty"`
	ReviewFocus       []string `json:"review_focus,omitempty"`
	Sources           []string `json:"sources,omitempty"`
	Dimensions        []string `json:"dimensions,omitempty"`
	Parallelism       int      `json:"parallelism,omitempty"`
}

type operationSpecRequest struct {
	Kind    string                  `json:"kind"`
	Scope   operationScopeRequest   `json:"scope"`
	Options operationOptionsRequest `json:"options,omitempty"`
}

type prepareRequest struct {
	Operation operationSpecRequest `json:"operation"`
}

type startRequest struct {
	Operation         operationSpecRequest `json:"operation"`
	ConfirmationToken string               `json:"confirmation_token"`
}

type preparationDTO struct {
	PreparationID     string         `json:"preparation_id"`
	Operation         map[string]any `json:"operation"`
	AffectedPaths     []string       `json:"affected_paths"`
	MutationClass     string         `json:"mutation_class"`
	Runtime           map[string]any `json:"runtime,omitempty"`
	Harness           map[string]any `json:"harness,omitempty"`
	Prerequisites     []string       `json:"prerequisites"`
	InputFingerprint  string         `json:"input_fingerprint"`
	ExpiresAt         time.Time      `json:"expires_at"`
	ConfirmationToken string         `json:"confirmation_token"`
}

type operationPreparationView struct {
	Preparation preparationDTO
	Spec        operationSpecRequest
}

func (h *handler) handleOperationPrepare(w http.ResponseWriter, r *http.Request) {
	if h.hub == nil || h.hub.ops == nil {
		h.writeOperationError(w, r, errors.New("operation capability unavailable"))
		return
	}
	if h.hub.isDraining() {
		h.writeOperationError(w, r, errServerDraining)
		return
	}
	var payload prepareRequest
	if err := decodeStrictJSON(r, &payload); err != nil {
		h.writeOperationError(w, r, err)
		return
	}
	req, err := mapOperationRequest(payload.Operation)
	if err != nil {
		h.writeOperationError(w, r, err)
		return
	}
	confirmation, err := h.hub.ops.PrepareOperation(r.Context(), req)
	if err != nil {
		h.writeOperationError(w, r, err)
		return
	}
	record, err := h.preparations.issue(sessionID(r.Context()), confirmation)
	if err != nil {
		h.writeOperationError(w, r, err)
		return
	}
	h.logOperation(r, "operation_prepared", "", string(confirmation.Request.Kind), "prepared", "")
	dto := preparationDTO{
		PreparationID: record.ID, Operation: mapOperationSpec(confirmation.Request), AffectedPaths: append([]string(nil), confirmation.Paths...),
		MutationClass: confirmation.MutationClass, Prerequisites: append([]string(nil), confirmation.Prerequisites...),
		InputFingerprint: confirmation.InputFingerprint, ExpiresAt: record.ExpiresAt, ConfirmationToken: record.Token,
	}
	if confirmation.Runtime {
		dto.Runtime = runtimeConfirmationDTO(confirmation)
	}
	if confirmation.Request.Kind == app.OperationSmokeStart || confirmation.Request.Kind == app.OperationSmokeDryRun {
		dto.Harness = map[string]any{"kind": "configured_smoke_harness"}
	}
	h.writeSuccess(w, r, http.StatusOK, dto, nil)
}

// runtimeConfirmationDTO projects the runtime identity confirmed for an
// operation, including any caller-requested model override.
func runtimeConfirmationDTO(confirmation app.Confirmation) map[string]any {
	runtime := map[string]any{"kind": "configured_runtime", "model_source": confirmation.ModelSource}
	if model := strings.TrimSpace(confirmation.Request.Model); model != "" {
		runtime["model"] = model
	}
	return runtime
}

func (h *handler) handleOperationStart(w http.ResponseWriter, r *http.Request) {
	if h.hub == nil || h.hub.ops == nil {
		h.writeOperationError(w, r, errors.New("operation capability unavailable"))
		return
	}
	var payload startRequest
	if err := decodeStrictJSON(r, &payload); err != nil {
		h.writeOperationError(w, r, err)
		return
	}
	if strings.TrimSpace(payload.ConfirmationToken) == "" {
		h.writeOperationError(w, r, fmt.Errorf("confirmation_token is required"))
		return
	}
	req, err := mapOperationRequest(payload.Operation)
	if err != nil {
		h.writeOperationError(w, r, err)
		return
	}
	current, err := h.hub.ops.PrepareOperation(r.Context(), req)
	if err != nil {
		h.writeOperationError(w, r, err)
		return
	}
	doc, err := h.hub.startConfirmed(sessionID(r.Context()), confirmationDedupKey(sessionID(r.Context()), payload.ConfirmationToken), func() (app.Confirmation, error) {
		return h.preparations.consume(payload.ConfirmationToken, sessionID(r.Context()), current.CanonicalRequest, current.InputFingerprint)
	})
	if err != nil {
		h.writeOperationError(w, r, err)
		return
	}
	w.Header().Set("Location", "/api/v1/operations/"+doc.ID)
	w.Header().Set("Link", "</api/v1/runs/"+doc.ID+">; rel=canonical")
	h.logOperation(r, "operation_started", doc.ID, string(doc.Kind), doc.State, "")
	h.writeSuccess(w, r, http.StatusAccepted, doc, nil)
}

func (h *handler) handleOperationStatus(w http.ResponseWriter, r *http.Request, id string) {
	doc, err := h.hub.status(sessionID(r.Context()), id)
	if err != nil {
		doc, err = h.durableOperationStatus(r.Context(), id)
	}
	if err != nil {
		if legacyOperationID(id) {
			h.writeError(w, r, http.StatusGone, "legacy_operation_not_retained", "This pre-durable operation is no longer retained. Refresh the owning product or inspect canonical workspace runs.")
			return
		}
		h.writeOperationError(w, r, err)
		return
	}
	h.writeSuccess(w, r, http.StatusOK, doc, nil)
}

func (h *handler) handleActiveOperations(w http.ResponseWriter, r *http.Request) {
	operations := h.hub.activeOperations(sessionID(r.Context()))
	if h.runs != nil {
		page, err := h.runs.Runs(r.Context(), app.RunQuery{Lifecycle: []app.RunLifecycle{"accepted", "queued", "running", "cancelling"}, TargetKind: "operation", Limit: 200})
		if err == nil {
			seen := make(map[string]bool, len(operations))
			for _, operation := range operations {
				seen[operation.ID] = true
			}
			for _, snapshot := range page.Runs {
				if seen[string(snapshot.RunID)] || !snapshot.Lifecycle.IsActive() || snapshot.Target.Kind != "operation" {
					continue
				}
				operations = append(operations, durableActiveOperation(snapshot))
			}
		}
	}
	count := len(operations)
	h.writeSuccess(w, r, http.StatusOK, operations, &app.CollectionInfo{ReturnedCount: count, TotalCount: count})
}

func (h *handler) handleOperationCancel(w http.ResponseWriter, r *http.Request, id string) {
	doc, requested, err := h.hub.cancelOperation(sessionID(r.Context()), id, "user_request")
	if err != nil && h.runs != nil {
		snapshot, changed, cancelErr := h.runs.CancelRun(r.Context(), app.RunID(id), "user_requested")
		if cancelErr == nil && string(snapshot.RunID) == id {
			doc, requested, err = durableOperationDocument(snapshot), changed, nil
		}
	}
	if err != nil {
		if legacyOperationID(id) {
			h.writeError(w, r, http.StatusGone, "legacy_operation_not_retained", "This pre-durable operation is no longer retained. Refresh the owning product or inspect canonical workspace runs.")
			return
		}
		h.writeOperationError(w, r, err)
		return
	}
	status := http.StatusOK
	if requested {
		status = http.StatusAccepted
	}
	h.logOperation(r, "operation_cancel", doc.ID, string(doc.Kind), doc.State, doc.Reason)
	h.writeSuccess(w, r, status, doc, nil)
}

func (h *handler) handleOperationEvents(w http.ResponseWriter, r *http.Request, id string) {
	lastID, err := parseEventID(r.Header.Get("Last-Event-ID"))
	if err != nil {
		h.writeOperationError(w, r, err)
		return
	}
	replay, events, unsubscribe, err := h.hub.subscribe(sessionID(r.Context()), id, lastID)
	if err != nil {
		if h.followDurableOperationEvents(w, r, id, lastID) {
			return
		}
		if legacyOperationID(id) {
			h.writeError(w, r, http.StatusGone, "legacy_operation_not_retained", "This pre-durable operation is no longer retained. Refresh the owning product or inspect canonical workspace runs.")
			return
		}
		h.writeOperationError(w, r, err)
		return
	}
	defer unsubscribe()
	flusher, ok := w.(http.Flusher)
	if !ok {
		h.writeOperationError(w, r, errors.New("streaming unavailable"))
		return
	}
	_ = http.NewResponseController(w).SetWriteDeadline(h.now().Add(MaxStreamLifetime + SSEHeartbeat))
	w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)
	for _, event := range replay {
		if err := writeSSEEvent(w, event); err != nil {
			return
		}
	}
	flusher.Flush()
	heartbeat := time.NewTicker(SSEHeartbeat)
	defer heartbeat.Stop()
	lifetime := time.NewTimer(MaxStreamLifetime)
	defer lifetime.Stop()
	for {
		select {
		case event, open := <-events:
			if !open {
				flusher.Flush()
				return
			}
			if err := writeSSEEvent(w, event); err != nil {
				return
			}
			flusher.Flush()
		case <-heartbeat.C:
			if _, err := io.WriteString(w, ": heartbeat\n\n"); err != nil {
				return
			}
			flusher.Flush()
		case <-lifetime.C:
			return
		case <-r.Context().Done():
			return
		}
	}
}

func (h *handler) handleHTMLOperationPrepare(w http.ResponseWriter, r *http.Request) {
	if err := r.ParseForm(); err != nil || r.FormValue("_csrf") != csrfToken(r.Context()) {
		h.renderError(w, r, http.StatusForbidden, "Request rejected", "The browser session or CSRF proof is invalid. Refresh the page and try again.")
		return
	}
	if h.hub == nil || h.hub.ops == nil || h.hub.isDraining() {
		h.renderError(w, r, http.StatusServiceUnavailable, "Server draining", "The server is not accepting new operations.")
		return
	}
	spec := operationSpecFromForm(r)
	req, err := mapOperationRequest(spec)
	if err != nil {
		h.renderError(w, r, http.StatusBadRequest, "Invalid operation", "The selected operation scope is invalid.")
		return
	}
	prepared, err := h.hub.ops.PrepareOperation(r.Context(), req)
	if err != nil {
		h.renderError(w, r, http.StatusUnprocessableEntity, "Preparation failed", htmlOperationFailure("The operation could not be prepared from current governed state.", err))
		return
	}
	record, err := h.preparations.issue(sessionID(r.Context()), prepared)
	if err != nil {
		h.renderError(w, r, http.StatusTooManyRequests, "Capacity reached", "Too many preparations are active. Wait briefly and retry.")
		return
	}
	dto := preparationDTO{
		PreparationID: record.ID, Operation: mapOperationSpec(prepared.Request), AffectedPaths: append([]string(nil), prepared.Paths...),
		MutationClass: prepared.MutationClass, Prerequisites: append([]string(nil), prepared.Prerequisites...),
		InputFingerprint: prepared.InputFingerprint, ExpiresAt: record.ExpiresAt, ConfirmationToken: record.Token,
	}
	if prepared.Runtime {
		dto.Runtime = runtimeConfirmationDTO(prepared)
	}
	view := &operationPreparationView{Preparation: dto, Spec: spec}
	h.render(w, r, http.StatusOK, "operation-confirm", pageModel{Title: "Confirm operation", Heading: "Confirm current operation scope", Preparation: view})
}

func (h *handler) handleHTMLOperationStart(w http.ResponseWriter, r *http.Request) {
	if err := r.ParseForm(); err != nil || r.FormValue("_csrf") != csrfToken(r.Context()) {
		h.renderError(w, r, http.StatusForbidden, "Request rejected", "The browser session or CSRF proof is invalid. Refresh and prepare again.")
		return
	}
	if h.hub == nil || h.hub.ops == nil {
		h.renderError(w, r, http.StatusServiceUnavailable, "Unavailable", "The operation capability is unavailable.")
		return
	}
	spec := operationSpecFromForm(r)
	req, err := mapOperationRequest(spec)
	if err != nil {
		h.renderError(w, r, http.StatusBadRequest, "Invalid operation", "The selected operation scope is invalid.")
		return
	}
	current, err := h.hub.ops.PrepareOperation(r.Context(), req)
	if err != nil {
		h.renderError(w, r, http.StatusUnprocessableEntity, "Preparation stale", htmlOperationFailure("The operation can no longer be prepared. Return to the owning page and prepare again.", err))
		return
	}
	token := r.FormValue("confirmation_token")
	doc, err := h.hub.startConfirmed(sessionID(r.Context()), confirmationDedupKey(sessionID(r.Context()), token), func() (app.Confirmation, error) {
		return h.preparations.consume(token, sessionID(r.Context()), current.CanonicalRequest, current.InputFingerprint)
	})
	if err != nil {
		h.renderError(w, r, http.StatusConflict, "Confirmation rejected", "The confirmation expired, changed, or was already used. Prepare the operation again.")
		return
	}
	h.logOperation(r, "operation_started", doc.ID, string(doc.Kind), doc.State, "")
	http.Redirect(w, r, "/operations/"+doc.ID, http.StatusSeeOther)
}

func (h *handler) handleHTMLOperationStatus(w http.ResponseWriter, r *http.Request, id string) {
	if h.runs != nil {
		if snapshot, runErr := h.runs.Run(r.Context(), app.RunID(id)); runErr == nil && string(snapshot.RunID) == id && snapshot.Target.Kind == "operation" {
			http.Redirect(w, r, "/runs/"+id, http.StatusSeeOther)
			return
		}
	}
	doc, err := h.hub.status(sessionID(r.Context()), id)
	if err != nil {
		if legacyOperationID(id) {
			h.renderError(w, r, http.StatusGone, "Legacy operation not retained", "This pre-durable operation expired. Refresh the owning product or open the workspace run list.")
			return
		}
		h.renderError(w, r, http.StatusNotFound, "Operation not retained", "Refresh the owning project, sprint, or study page for durable status.")
		return
	}
	h.render(w, r, http.StatusOK, "operation", pageModel{Title: "Operation " + doc.ID, Heading: "Operation status", Operation: &doc})
}

func (h *handler) handleHTMLOperationCancel(w http.ResponseWriter, r *http.Request, id string) {
	if err := r.ParseForm(); err != nil || r.FormValue("_csrf") != csrfToken(r.Context()) {
		h.renderError(w, r, http.StatusForbidden, "Request rejected", "The browser session or CSRF proof is invalid. Refresh the operation page and try again.")
		return
	}
	if h.hub == nil {
		h.renderError(w, r, http.StatusServiceUnavailable, "Unavailable", "The operation capability is unavailable.")
		return
	}
	doc, requested, err := h.hub.cancelOperation(sessionID(r.Context()), id, "user_request")
	if err != nil && h.runs != nil {
		snapshot, changed, cancelErr := h.runs.CancelRun(r.Context(), app.RunID(id), "user_requested")
		if cancelErr == nil && string(snapshot.RunID) == id {
			doc, requested, err = durableOperationDocument(snapshot), changed, nil
		}
	}
	if err != nil {
		if legacyOperationID(id) {
			h.renderError(w, r, http.StatusGone, "Legacy operation not retained", "This pre-durable operation expired. Refresh the owning product or open the workspace run list.")
			return
		}
		h.renderError(w, r, http.StatusNotFound, "Operation not retained", "Refresh the owning project, sprint, or study page for durable status.")
		return
	}
	if requested {
		h.logOperation(r, "operation_cancel_requested", doc.ID, string(doc.Kind), doc.State, doc.Reason)
	}
	http.Redirect(w, r, "/operations/"+doc.ID, http.StatusSeeOther)
}

func (h *handler) durableOperationStatus(ctx context.Context, id string) (operationDocument, error) {
	if h.runs == nil {
		return operationDocument{}, errOperationNotFound
	}
	snapshot, err := h.runs.Run(ctx, app.RunID(id))
	if err != nil || string(snapshot.RunID) != id || snapshot.Target.Kind != "operation" {
		return operationDocument{}, errOperationNotFound
	}
	return durableOperationDocument(snapshot), nil
}

func legacyOperationID(id string) bool { return strings.HasPrefix(id, "op_") }

func durableOperationDocument(snapshot app.RunSnapshot) operationDocument {
	reason := snapshot.Cancellation.Reason
	if snapshot.Terminal != nil && snapshot.Terminal.Reason != "" {
		reason = snapshot.Terminal.Reason
	}
	return operationDocument{
		ID: string(snapshot.RunID), Kind: app.OperationKind(snapshot.Target.Operation), State: string(snapshot.Lifecycle), Reason: reason,
		CreatedAt: snapshot.AcceptedAt, StartedAt: snapshot.StartedAt, FinishedAt: snapshot.FinishedAt,
		LastEventID:   strconv.FormatUint(snapshot.LastSequence, 10),
		DurableStatus: durableStatusDTO{Available: true, RefreshPath: "/runs/" + string(snapshot.RunID)},
	}
}

func durableActiveOperation(snapshot app.RunSnapshot) activeOperationDTO {
	return activeOperationDTO{
		ID: string(snapshot.RunID), Kind: app.OperationKind(snapshot.Target.Operation), State: string(snapshot.Lifecycle),
		Project: snapshot.Target.Project, Sprint: snapshot.Target.Sprint, Study: snapshot.Target.Study, StartedAt: snapshot.StartedAt,
	}
}

// followDurableOperationEvents is the compatibility projection for a run that
// was accepted by this or another local server but is absent from this
// process's transient operation hub.
func (h *handler) followDurableOperationEvents(w http.ResponseWriter, r *http.Request, id string, after uint64) bool {
	if h.runs == nil {
		return false
	}
	snapshot, err := h.runs.Run(r.Context(), app.RunID(id))
	if err != nil || string(snapshot.RunID) != id || snapshot.Target.Kind != "operation" {
		return false
	}
	if after > snapshot.LastSequence {
		h.writeError(w, r, http.StatusConflict, "cursor_ahead", "The event cursor is ahead of the durable operation.")
		return true
	}
	if after+1 < snapshot.OldestRetainedSequence {
		h.writeError(w, r, http.StatusConflict, "replay_gap", "The requested operation history is no longer retained; refresh its canonical run.")
		return true
	}
	flusher, ok := w.(http.Flusher)
	if !ok {
		h.writeOperationError(w, r, errors.New("streaming unavailable"))
		return true
	}
	w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)
	flusher.Flush()
	heartbeat := time.NewTicker(SSEHeartbeat)
	defer heartbeat.Stop()
	lifetime := time.NewTimer(MaxStreamLifetime)
	defer lifetime.Stop()
	poll := time.NewTimer(0)
	defer poll.Stop()
	for {
		select {
		case <-poll.C:
			events, eventErr := h.runs.RunEvents(r.Context(), snapshot.RunID, after, 512)
			if eventErr != nil {
				return true
			}
			for _, event := range events {
				projected := durableOperationEvent(event)
				if err := writeSSEEvent(w, projected); err != nil {
					return true
				}
				after = event.Sequence
			}
			flusher.Flush()
			snapshot, eventErr = h.runs.Run(r.Context(), snapshot.RunID)
			if eventErr != nil || snapshot.Lifecycle.IsTerminal() && after >= snapshot.LastSequence {
				return true
			}
			wait := time.Second
			if len(events) == 512 || after < snapshot.LastSequence {
				wait = 250 * time.Millisecond
			}
			poll.Reset(wait)
		case <-heartbeat.C:
			if _, err := io.WriteString(w, ": heartbeat\n\n"); err != nil {
				return true
			}
			flusher.Flush()
		case <-lifetime.C:
			return true
		case <-r.Context().Done():
			return true
		}
	}
}

func durableOperationEvent(event app.RunEvent) operationEvent {
	name := "progress"
	switch string(event.Type) {
	case "accepted", "claimed", "lifecycle":
		name = "snapshot"
	case "warning", "finding", "artifact", "terminal":
		name = string(event.Type)
	case "cancellation":
		name = "cancel_requested"
	case "recovery", "omission":
		name = "recovery_required"
	}
	payload := map[string]any{"stage": event.Stage, "task": event.Task, "payload": event.Payload, "omission": event.Omission}
	body, _ := json.Marshal(map[string]any{
		"operation_id": string(event.RunID), "time": event.CommittedAt.UTC().Format(time.RFC3339Nano),
		"sequence": event.Sequence, "payload": payload,
	})
	return operationEvent{ID: event.Sequence, Name: name, Data: body}
}

func operationSpecFromForm(r *http.Request) operationSpecRequest {
	parallelism, _ := strconv.Atoi(r.FormValue("parallelism"))
	sprintRef := r.FormValue("sprint")
	if sprintRef == "" {
		sprintRef = newSprintRef(r.FormValue("sprint_number"), r.FormValue("sprint_name"))
	}
	return operationSpecRequest{
		Kind:  r.FormValue("kind"),
		Scope: operationScopeRequest{Project: r.FormValue("project"), Sprint: sprintRef, Study: r.FormValue("study")},
		Options: operationOptionsRequest{
			ToStage:     r.FormValue("stage"),
			Task:        r.FormValue("task"),
			Shard:       r.FormValue("shard"),
			Model:       strings.TrimSpace(r.FormValue("model")),
			Suite:       strings.TrimSpace(r.FormValue("suite")),
			Parallelism: parallelism,
		},
	}
}

func newSprintRef(number, name string) string {
	number = strings.TrimSpace(number)
	name = strings.TrimSpace(name)
	if number == "" || name == "" {
		return ""
	}
	for _, r := range number {
		if r < '0' || r > '9' {
			return number + "-" + name
		}
	}
	var slug strings.Builder
	separator := false
	for _, r := range strings.ToLower(name) {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
			if separator && slug.Len() > 0 {
				slug.WriteByte('-')
			}
			slug.WriteRune(r)
			separator = false
		case r == ' ' || r == '-' || r == '_':
			separator = true
		default:
			return number + "-" + name
		}
	}
	if slug.Len() == 0 {
		return ""
	}
	return number + "-" + slug.String()
}

func writeSSEEvent(w io.Writer, event operationEvent) error {
	_, err := fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", event.ID, event.Name, event.Data)
	return err
}

func decodeStrictJSON(r *http.Request, target any) error {
	contentType := r.Header.Get("Content-Type")
	if !strings.HasPrefix(strings.ToLower(contentType), "application/json") {
		return fmt.Errorf("Content-Type must be application/json")
	}
	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		return fmt.Errorf("invalid JSON request: %w", err)
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		return fmt.Errorf("request must contain one JSON value")
	}
	return nil
}

func mapOperationRequest(spec operationSpecRequest) (app.OperationRequest, error) {
	if !validOptionalIdentifier(spec.Scope.Project) || !validOptionalIdentifier(spec.Scope.Sprint) || !validOptionalIdentifier(spec.Scope.Study) {
		return app.OperationRequest{}, fmt.Errorf("operation scope contains an invalid identifier")
	}
	options := spec.Options
	req := app.OperationRequest{
		Project: spec.Scope.Project, Sprint: spec.Scope.Sprint, Study: spec.Scope.Study,
		Stage: firstString(options.ToStage, options.Stage), Task: options.Task, Model: options.Model,
		Level: options.Level, Suite: options.Suite, Test: options.Test, Timeout: options.Timeout,
		ForceReview: options.ForceReview, RestartReview: options.RestartReview, OverrideRationale: options.OverrideRationale,
		ReviewFocus: options.ReviewFocus, Sources: options.Sources, Dimensions: options.Dimensions, Parallelism: options.Parallelism,
	}
	kind := strings.ReplaceAll(strings.TrimSpace(spec.Kind), "_", "-")
	switch kind {
	case "validation", "validate":
		req.Kind = app.OperationValidate
	case "sprint-status":
		req.Kind = app.OperationSprintStatus
	case "prompt-preview", "sprint-prompt":
		req.Kind = app.OperationPrompt
	case "dry-run", "sprint-flow-dry-run":
		req.Kind = app.OperationFlowDryRun
	case "sprint-flow":
		if options.DryRun {
			req.Kind = app.OperationFlowDryRun
		} else {
			req.Kind = app.OperationFlow
		}
	case "sprint-stage":
		if options.DryRun {
			req.Kind = app.OperationStageDryRun
		} else {
			req.Kind = app.OperationStage
		}
	case "sprint-stage-dry-run":
		req.Kind = app.OperationStageDryRun
	case "execute", "execute-start":
		switch {
		case options.Action == "status":
			req.Kind = app.OperationExecuteStatus
		case options.DryRun:
			req.Kind = app.OperationExecuteDryRun
		case options.Resume:
			req.Kind = app.OperationExecuteResume
		default:
			req.Kind = app.OperationExecuteStart
		}
	case "execute-status":
		req.Kind = app.OperationExecuteStatus
	case "execute-dry-run":
		req.Kind = app.OperationExecuteDryRun
	case "execute-resume":
		req.Kind = app.OperationExecuteResume
	case "review", "review-start":
		if options.Action == "status" {
			req.Kind = app.OperationReviewStatus
		} else if options.DryRun {
			req.Kind = app.OperationReviewDryRun
		} else {
			req.Kind = app.OperationReviewStart
		}
	case "review-status":
		req.Kind = app.OperationReviewStatus
	case "review-dry-run":
		req.Kind = app.OperationReviewDryRun
	case "smoke", "smoke-start":
		if options.Action == "status" {
			req.Kind = app.OperationSmokeStatus
		} else if options.DryRun {
			req.Kind = app.OperationSmokeDryRun
		} else {
			req.Kind = app.OperationSmokeStart
		}
	case "smoke-status":
		req.Kind = app.OperationSmokeStatus
	case "smoke-dry-run":
		req.Kind = app.OperationSmokeDryRun
	case "verify", "verify-start":
		if options.DryRun {
			req.Kind = app.OperationVerifyDryRun
		} else {
			req.Kind = app.OperationVerifyStart
		}
	case "verify-dry-run":
		req.Kind = app.OperationVerifyDryRun
	case "qa-status":
		req.Kind = app.OperationQAStatus
	case "qa-dry-run":
		req.Kind = app.OperationQADryRun
	case "qa-start":
		req.Kind = app.OperationQAStart
		req.Task = options.Shard
	case "qa-resume":
		req.Kind = app.OperationQAResume
		req.Task = options.Shard
	case "qa-recover":
		req.Kind = app.OperationQARecover
	case "study-run-loop", "study-start":
		if options.Resume {
			req.Kind = app.OperationStudyResume
		} else {
			req.Kind = app.OperationStudyStart
		}
	case "study-resume":
		req.Kind = app.OperationStudyResume
	case "study-cancel":
		req.Kind = app.OperationStudyCancel
	default:
		return app.OperationRequest{}, fmt.Errorf("unsupported operation kind %q", spec.Kind)
	}
	if req.Kind == app.OperationValidate {
		if (req.Project == "") == (req.Study == "") {
			return app.OperationRequest{}, fmt.Errorf("validation requires one project or study scope")
		}
	} else if strings.HasPrefix(string(req.Kind), "study-") {
		if req.Study == "" || req.Project != "" || req.Sprint != "" {
			return app.OperationRequest{}, fmt.Errorf("study operations require only scope.study")
		}
	} else if req.Project == "" {
		return app.OperationRequest{}, fmt.Errorf("project operations require scope.project")
	} else if req.Sprint == "" {
		return app.OperationRequest{}, fmt.Errorf("sprint operations require scope.sprint")
	}
	if strings.HasPrefix(string(req.Kind), "qa-") {
		if options.Task != "" || options.Model != "" || options.Stage != "" || options.ToStage != "" || options.Action != "" || options.DryRun || options.Resume || options.Level != "" || options.Test != "" || options.Timeout != "" || options.ForceReview || options.RestartReview || options.OverrideRationale != "" || len(options.ReviewFocus) > 0 || len(options.Sources) > 0 || len(options.Dimensions) > 0 || options.Parallelism != 0 {
			return app.OperationRequest{}, fmt.Errorf("QA operations accept only options.shard or options.suite")
		}
		if options.Suite != "" && options.Suite != "smoke" {
			return app.OperationRequest{}, fmt.Errorf("QA options.suite must be smoke")
		}
		if options.Suite != "" && req.Kind != app.OperationQAStart && req.Kind != app.OperationQADryRun {
			return app.OperationRequest{}, fmt.Errorf("QA suite is valid only for start or dry-run")
		}
		if options.Suite != "" && options.Shard != "" {
			return app.OperationRequest{}, fmt.Errorf("QA suite and shard are mutually exclusive")
		}
		req.Suite = options.Suite
		if options.Shard != "" && req.Kind != app.OperationQAStart && req.Kind != app.OperationQAResume {
			return app.OperationRequest{}, fmt.Errorf("QA shard is valid only for start or resume")
		}
	}
	return req, nil
}

func mapOperationSpec(req app.OperationRequest) map[string]any {
	scope := map[string]any{}
	if req.Project != "" {
		scope["project"] = req.Project
	}
	if req.Sprint != "" {
		scope["sprint"] = req.Sprint
	}
	if req.Study != "" {
		scope["study"] = req.Study
	}
	options := map[string]any{}
	if req.Stage != "" {
		options["stage"] = req.Stage
	}
	if req.Task != "" {
		if req.Kind == app.OperationQAStart || req.Kind == app.OperationQAResume {
			options["shard"] = req.Task
		} else {
			options["task"] = req.Task
		}
	}
	if req.Model != "" {
		options["model"] = req.Model
	}
	if req.Parallelism > 0 {
		options["parallelism"] = req.Parallelism
	}
	if req.Suite != "" {
		options["suite"] = req.Suite
	}
	return map[string]any{"kind": req.Kind, "scope": scope, "options": options}
}

func validOptionalIdentifier(value string) bool {
	return value == "" || validIdentifier(value)
}

func firstString(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

func (h *handler) writeOperationError(w http.ResponseWriter, r *http.Request, err error) {
	status, code, message, retryable := http.StatusBadRequest, "invalid_request", "The operation request is invalid.", false
	details := map[string]any{}
	switch {
	case errors.Is(err, errConfirmationExpired):
		status, code, message, retryable = http.StatusConflict, "confirmation_expired", "The confirmation expired. Prepare the operation again.", true
	case errors.Is(err, errConfirmationMismatch):
		status, code, message = http.StatusConflict, "confirmation_mismatch", "The confirmation does not match this session or operation."
	case errors.Is(err, errConfirmationReplayed):
		status, code, message = http.StatusConflict, "confirmation_replayed", "The confirmation was already used or is unknown."
	case errors.Is(err, errStaleConfirmation), errors.Is(err, app.ErrStaleOperation):
		status, code, message, retryable = http.StatusConflict, "stale_confirmation", "The operation inputs changed after confirmation. Prepare it again.", true
	case errors.Is(err, errOperationNotFound):
		status, code, message = http.StatusNotFound, "operation_not_found", "The operation is no longer retained. Refresh durable status."
		details["action"] = "refresh_durable_status"
	case errors.Is(err, errOperationCapacity):
		status, code, message, retryable = http.StatusTooManyRequests, "operation_capacity", "Operation capacity is currently full.", true
		w.Header().Set("Retry-After", "2")
	case errors.Is(err, errSubscriberCapacity):
		status, code, message, retryable = http.StatusTooManyRequests, "subscriber_capacity", "Stream capacity is currently full.", true
		w.Header().Set("Retry-After", "2")
	case errors.Is(err, errServerDraining):
		status, code, message, retryable = http.StatusServiceUnavailable, "server_draining", "The server is shutting down and is not accepting new work.", true
		w.Header().Set("Retry-After", "2")
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		status, code, message, retryable = http.StatusServiceUnavailable, "server_draining", "The server is shutting down.", true
	case strings.Contains(strings.ToLower(err.Error()), "validation"), strings.Contains(strings.ToLower(err.Error()), "incomplete"), strings.Contains(strings.ToLower(err.Error()), "prerequisite"):
		status, code, message = http.StatusUnprocessableEntity, "validation_failed", "The governed inputs failed validation."
	case strings.Contains(strings.ToLower(err.Error()), "lock"), strings.Contains(strings.ToLower(err.Error()), "in progress"):
		status, code, message, retryable = http.StatusConflict, "operation_conflict", "A conflicting operation is already running.", true
	case strings.Contains(strings.ToLower(err.Error()), "unavailable"):
		status, code, message, retryable = http.StatusFailedDependency, "prerequisite_unavailable", "A required operation prerequisite is unavailable.", true
	case !isClientOperationError(err):
		status, code, message = http.StatusInternalServerError, "internal_failure", "The operation could not be completed."
	}
	if cause := safeOperationCause(err); cause != "" && status < http.StatusInternalServerError {
		details["reason"] = cause
		details["guidance"] = operationFailureGuidance(code)
	}
	h.writeErrorDetails(w, r, status, errorBody{Code: code, Message: message, Retryable: retryable, Details: details})
}

func safeOperationCause(err error) string {
	if err == nil {
		return ""
	}
	text := strings.ToLower(err.Error())
	if isClientOperationError(err) || strings.Contains(text, "validation") || strings.Contains(text, "incomplete") || strings.Contains(text, "prerequisite") || strings.Contains(text, "lock") || strings.Contains(text, "in progress") || strings.Contains(text, "unavailable") {
		return safeWebText(err.Error())
	}
	return ""
}

func operationFailureGuidance(code string) string {
	switch code {
	case "validation_failed":
		return "Open the sprint Plan and Delivery pages, correct the reported incomplete or invalid evidence, then retry."
	case "operation_conflict":
		return "Wait for the active operation to finish or inspect and cancel it before retrying."
	case "prerequisite_unavailable":
		return "Restore the missing prerequisite or runtime capability, then prepare the operation again."
	default:
		return "Correct the reported reason and prepare the operation again."
	}
}

func htmlOperationFailure(summary string, err error) string {
	cause := safeOperationCause(err)
	if cause == "" {
		return summary
	}
	return summary + " Reason: " + cause + " Correct the reported prerequisite or governed artifact, then retry."
}

func isClientOperationError(err error) bool {
	text := strings.ToLower(err.Error())
	return strings.Contains(text, "required") || strings.Contains(text, "invalid") || strings.Contains(text, "unsupported") || strings.Contains(text, "json") || strings.Contains(text, "content-type") || strings.Contains(text, "scope")
}

func (h *handler) writeErrorDetails(w http.ResponseWriter, r *http.Request, status int, body errorBody) {
	meta := responseMeta{APIVersion: "v1", RequestID: requestID(r.Context()), GeneratedAt: h.now().UTC().Format(time.RFC3339Nano)}
	writeJSON(w, status, errorEnvelope{Error: body, Meta: meta})
}

func eventIDHeader(value string) string {
	if value == "" {
		return "0"
	}
	if _, err := strconv.ParseUint(value, 10, 64); err != nil {
		return "0"
	}
	return value
}

func (h *handler) logOperation(r *http.Request, event, operationID, kind, state, reason string) {
	fmt.Fprintf(h.diagnostics,
		"event=%s request_id=%s operation_id=%s kind=%s state=%s reason=%s\n",
		safeWebText(event), safeWebText(requestID(r.Context())), safeWebText(operationID), safeWebText(kind), safeWebText(state), safeWebText(reason))
}

package web

import (
	"context"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

const (
	MaxBodyBytes       = 64 * 1024
	MaxRequestTarget   = 8 * 1024
	MaxIdentifierBytes = 128
)

type requestIDKey struct{}
type sessionIDKey struct{}
type csrfTokenKey struct{}

type trackedWriter struct {
	http.ResponseWriter
	status int
	bytes  int
}

func (w *trackedWriter) Unwrap() http.ResponseWriter { return w.ResponseWriter }

func (w *trackedWriter) WriteHeader(status int) {
	if w.status != 0 {
		return
	}
	w.status = status
	w.ResponseWriter.WriteHeader(status)
}

func (w *trackedWriter) Write(data []byte) (int, error) {
	if w.status == 0 {
		w.WriteHeader(http.StatusOK)
	}
	n, err := w.ResponseWriter.Write(data)
	w.bytes += n
	return n, err
}

func (w *trackedWriter) Flush() {
	if w.status == 0 {
		w.WriteHeader(http.StatusOK)
	}
	if flusher, ok := w.ResponseWriter.(http.Flusher); ok {
		flusher.Flush()
	}
}

type securityMiddleware struct {
	authority   string
	origin      string
	diagnostics io.Writer
	now         func() time.Time
	requestID   func() string
	sem         chan struct{}
	active      atomic.Int64
	secret      [32]byte
}

func newSecurityMiddleware(authority string, diagnostics io.Writer, now func() time.Time, requestID func() string) *securityMiddleware {
	if diagnostics == nil {
		diagnostics = io.Discard
	}
	if now == nil {
		now = time.Now
	}
	if requestID == nil {
		requestID = randomRequestID
	}
	m := &securityMiddleware{
		authority:   authority,
		origin:      "http://" + authority,
		diagnostics: diagnostics,
		now:         now,
		requestID:   requestID,
		sem:         make(chan struct{}, MaxInFlight),
	}
	if _, err := rand.Read(m.secret[:]); err != nil {
		m.secret = sha256.Sum256([]byte(authority + now().UTC().Format(time.RFC3339Nano)))
	}
	return m
}

func (m *securityMiddleware) wrap(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		started := m.now()
		tracked := &trackedWriter{ResponseWriter: w}
		applySecurityHeaders(tracked.Header())
		id := m.requestID()
		tracked.Header().Set("X-Request-ID", id)
		r = r.WithContext(context.WithValue(r.Context(), requestIDKey{}, id))
		session, validSession := m.readSession(r)
		if !validSession {
			session = randomRequestID()
			http.SetCookie(tracked, &http.Cookie{Name: "ultraplan_session", Value: m.signSession(session), Path: "/", HttpOnly: true, SameSite: http.SameSiteStrictMode, MaxAge: 3600})
		}
		csrf := m.csrfFor(session)
		tracked.Header().Set("X-CSRF-Token", csrf)
		ctx := context.WithValue(r.Context(), sessionIDKey{}, session)
		ctx = context.WithValue(ctx, csrfTokenKey{}, csrf)
		r = r.WithContext(ctx)

		select {
		case m.sem <- struct{}{}:
			m.active.Add(1)
			defer func() {
				m.active.Add(-1)
				<-m.sem
			}()
		case <-r.Context().Done():
			m.reject(tracked, r, http.StatusServiceUnavailable, "unavailable", "The service is unavailable.")
			return
		}

		matchedRoute := matchRoute(r.URL.Path)
		apiOperationMutation := (r.Method == http.MethodPost || r.Method == http.MethodDelete) && strings.HasPrefix(r.URL.Path, "/api/v1/operations")
		apiRunMutation := r.Method == http.MethodDelete && matchedRoute.name == "api_run"
		htmlOperationMutation := r.Method == http.MethodPost && strings.HasPrefix(r.URL.Path, "/operations/")
		htmlSprintMutation := r.Method == http.MethodPost && matchedRoute.name == "sprint_create"
		htmlRunMutation := r.Method == http.MethodPost && matchedRoute.name == "run_cancel"
		operationMutation := apiOperationMutation || apiRunMutation || htmlOperationMutation || htmlSprintMutation || htmlRunMutation
		operationRead := (r.Method == http.MethodGet || r.Method == http.MethodHead) && (matchedRoute.name == "api_operation" || matchedRoute.name == "api_operation_events")
		staticAsset := (r.Method == http.MethodGet || r.Method == http.MethodHead) && strings.HasPrefix(r.URL.Path, "/static/")
		hasBody := r.ContentLength > 0 || len(r.TransferEncoding) > 0
		operationBody := r.Method == http.MethodPost && (matchedRoute.name == "api_operation_prepare" || matchedRoute.name == "api_operations" || matchedRoute.name == "operation_prepare" || matchedRoute.name == "operation_start" || matchedRoute.name == "operation_cancel" || matchedRoute.name == "run_cancel" || matchedRoute.name == "sprint_create")
		switch {
		case len(r.RequestURI) > MaxRequestTarget:
			m.reject(tracked, r, http.StatusBadRequest, "invalid_request", "The request target is too long.")
		case ambiguousRequestFraming(r):
			m.reject(tracked, r, http.StatusBadRequest, "invalid_request", "The request framing is ambiguous.")
		case r.Host != m.authority:
			m.reject(tracked, r, http.StatusForbidden, "host_rejected", hostRejectionMessage(m.authority, r.Host))
		case operationMutation && !validSession:
			m.reject(tracked, r, http.StatusForbidden, "session_required", "Establish a browser session before submitting commands.")
		case operationMutation && !validCommandRequestOrigin(r, m.origin):
			m.reject(tracked, r, http.StatusForbidden, "origin_rejected", originRejectionMessage(m.origin, r.Header.Get("Origin")))
		case (apiOperationMutation || apiRunMutation) && subtle.ConstantTimeCompare([]byte(r.Header.Get("X-CSRF-Token")), []byte(csrf)) != 1:
			m.reject(tracked, r, http.StatusForbidden, "csrf_failed", "The CSRF proof did not match this browser session. Refresh the UltraPlan page and prepare the operation again.")
		case operationRead && !validOperationReadRequestOrigin(r, m.origin):
			m.reject(tracked, r, http.StatusForbidden, "origin_rejected", originRejectionMessage(m.origin, r.Header.Get("Origin")))
		case !operationMutation && !operationRead && !staticAsset && !validReadRequestOrigin(r, m.origin):
			m.reject(tracked, r, http.StatusForbidden, "origin_rejected", originRejectionMessage(m.origin, r.Header.Get("Origin")))
		case r.ContentLength > MaxBodyBytes:
			m.reject(tracked, r, http.StatusRequestEntityTooLarge, "request_too_large", "The request is too large.")
		case hasBody && !operationBody:
			m.reject(tracked, r, http.StatusBadRequest, "invalid_request", "Request bodies are not accepted.")
		default:
			if operationBody {
				r.Body = http.MaxBytesReader(tracked, r.Body, MaxBodyBytes)
			}
			next.ServeHTTP(tracked, r)
		}
		if tracked.status == 0 {
			tracked.status = http.StatusOK
		}
		fmt.Fprintf(m.diagnostics,
			"event=http_request request_id=%s route=%s method=%s status=%d duration_ms=%d response_bytes=%d\n",
			id, normalizedRoute(r.URL.Path), r.Method, tracked.status, m.now().Sub(started).Milliseconds(), tracked.bytes)
	})
}

func ambiguousRequestFraming(r *http.Request) bool {
	contentLengths := r.Header.Values("Content-Length")
	return len(contentLengths) > 1 || (len(contentLengths) > 0 && len(r.TransferEncoding) > 0)
}

func (m *securityMiddleware) reject(w http.ResponseWriter, r *http.Request, status int, code, message string) {
	fmt.Fprintf(m.diagnostics, "event=security_rejection request_id=%s route=%s method=%s status=%d code=%s\n", requestID(r.Context()), normalizedRoute(r.URL.Path), r.Method, status, code)
	writePolicyError(w, r, status, code, message)
}

func originRejectionMessage(expected, received string) string {
	return fmt.Sprintf("The browser sent the request from %s, but this server only accepts commands from %s. Open the exact Dashboard URL printed by UltraPlan, refresh it, and retry.", displayOrigin(received), expected)
}

func hostRejectionMessage(expected, received string) string {
	return fmt.Sprintf("The request used host %s, but this server is listening as %s. Open the exact Dashboard URL printed by UltraPlan.", displayAuthority(received), expected)
}

func displayOrigin(value string) string {
	if value == "" {
		return "a request with no Origin header"
	}
	if value == "null" {
		return "the opaque origin 'null'"
	}
	parsed, err := url.Parse(value)
	if err != nil || parsed.Scheme == "" || parsed.Host == "" || parsed.User != nil {
		return "an invalid origin"
	}
	return parsed.Scheme + "://" + displayAuthority(parsed.Host)
}

func displayAuthority(value string) string {
	value = strings.Map(func(r rune) rune {
		if r < 0x20 || r == 0x7f {
			return -1
		}
		return r
	}, value)
	if len(value) > 256 {
		value = value[:256] + "…"
	}
	if value == "" {
		return "an empty host"
	}
	return value
}

func (m *securityMiddleware) signSession(session string) string {
	mac := hmac.New(sha256.New, m.secret[:])
	_, _ = mac.Write([]byte("session:" + session))
	return session + "." + hex.EncodeToString(mac.Sum(nil))
}

func (m *securityMiddleware) readSession(r *http.Request) (string, bool) {
	cookie, err := r.Cookie("ultraplan_session")
	if err != nil {
		return "", false
	}
	parts := strings.Split(cookie.Value, ".")
	if len(parts) != 2 || len(parts[0]) != 32 {
		return "", false
	}
	expected := m.signSession(parts[0])
	return parts[0], subtle.ConstantTimeCompare([]byte(cookie.Value), []byte(expected)) == 1
}

func (m *securityMiddleware) csrfFor(session string) string {
	mac := hmac.New(sha256.New, m.secret[:])
	_, _ = mac.Write([]byte("csrf:" + session))
	return hex.EncodeToString(mac.Sum(nil))
}

func applySecurityHeaders(header http.Header) {
	header.Set("Cache-Control", "no-store")
	header.Set("Content-Security-Policy", "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")
	header.Set("Referrer-Policy", "same-origin")
	header.Set("X-Content-Type-Options", "nosniff")
	header.Set("X-Frame-Options", "DENY")
	header.Set("Permissions-Policy", "camera=(), microphone=(), geolocation=()")
}

func validOrigin(origin, expected string) bool {
	if origin == "" {
		return true
	}
	return validCommandOrigin(origin, expected)
}

// validCommandOrigin permits a browser shell or local reverse proxy to omit or
// rewrite only the port while preserving the exact numeric loopback address.
// Mutating requests still require the signed session and CSRF proof.
func validCommandOrigin(origin, expected string) bool {
	return origin == expected
}

// validCommandRequestOrigin accepts the exact configured origin. It also
// tolerates browsers that remove a non-default port from Origin when their
// unforgeable fetch metadata and exact Referer still prove a same-origin
// request. Session and CSRF validation remain separate mandatory checks.
func validCommandRequestOrigin(r *http.Request, expected string) bool {
	if validCommandOrigin(r.Header.Get("Origin"), expected) {
		return true
	}
	if r.Header.Get("Sec-Fetch-Site") != "same-origin" {
		return false
	}
	receivedURL, receivedErr := url.Parse(r.Header.Get("Origin"))
	expectedURL, expectedErr := url.Parse(expected)
	refererURL, refererErr := url.Parse(r.Header.Get("Referer"))
	if receivedErr != nil || expectedErr != nil || refererErr != nil ||
		receivedURL.User != nil || expectedURL.User != nil || refererURL.User != nil {
		return false
	}
	return receivedURL.Scheme == expectedURL.Scheme &&
		receivedURL.Hostname() == expectedURL.Hostname() &&
		receivedURL.Port() == "" && expectedURL.Port() != "" &&
		refererURL.Scheme+"://"+refererURL.Host == expected
}

func validOperationReadOrigin(origin, expected string) bool {
	return origin == "" || validCommandOrigin(origin, expected)
}

func validOperationReadRequestOrigin(r *http.Request, expected string) bool {
	return r.Header.Get("Origin") == "" || validCommandRequestOrigin(r, expected)
}

// validReadRequestOrigin applies the browser's same-origin proofs to ordinary
// read-only pages and APIs too. Some browser shells normalize a loopback
// Origin by dropping its non-default port, even though Host and Referer retain
// the exact authority. Mutations continue through the stricter command path.
func validReadRequestOrigin(r *http.Request, expected string) bool {
	return r.Header.Get("Origin") == "" || validCommandRequestOrigin(r, expected)
}

func requestID(ctx context.Context) string {
	id, _ := ctx.Value(requestIDKey{}).(string)
	return id
}

func sessionID(ctx context.Context) string {
	id, _ := ctx.Value(sessionIDKey{}).(string)
	return id
}

func csrfToken(ctx context.Context) string {
	token, _ := ctx.Value(csrfTokenKey{}).(string)
	return token
}

func randomRequestID() string {
	var data [16]byte
	if _, err := rand.Read(data[:]); err != nil {
		return "00000000000000000000000000000000"
	}
	return hex.EncodeToString(data[:])
}

func normalizedRoute(path string) string {
	switch {
	case path == "/":
		return "dashboard"
	case path == "/projects":
		return "projects"
	case strings.HasPrefix(path, "/projects/") && strings.Contains(path, "/sprints/"):
		return "sprint_detail"
	case strings.HasPrefix(path, "/projects/"):
		return "project_detail"
	case path == "/studies":
		return "studies"
	case strings.HasPrefix(path, "/studies/"):
		return "study_detail"
	case strings.HasPrefix(path, "/artifacts/"):
		return "artifact"
	case strings.HasPrefix(path, "/api/v1/artifacts/"):
		return "api_artifact"
	case strings.HasPrefix(path, "/api/v1/"):
		return "api_v1"
	case strings.HasPrefix(path, "/api/"):
		return "api_unknown"
	case strings.HasPrefix(path, "/static/"):
		return "static"
	default:
		return "not_found"
	}
}

type preparationRecord struct {
	ID           string
	Token        string
	Session      string
	Canonical    string
	Fingerprint  string
	Confirmation app.Confirmation
	ExpiresAt    time.Time
	Consumed     bool
}

type preparationStore struct {
	mu      sync.Mutex
	now     func() time.Time
	id      func() string
	records map[string]*preparationRecord
}

func newPreparationStore(now func() time.Time, id func() string) *preparationStore {
	if now == nil {
		now = time.Now
	}
	if id == nil {
		id = randomRequestID
	}
	return &preparationStore{now: now, id: id, records: make(map[string]*preparationRecord)}
}

func (s *preparationStore) issue(session string, confirmation app.Confirmation) (*preparationRecord, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.reapLocked()
	if len(s.records) >= MaxPreparations {
		return nil, errOperationCapacity
	}
	record := &preparationRecord{
		ID: "prep_" + s.id(), Token: "confirm_" + s.id(), Session: session,
		Canonical: confirmation.CanonicalRequest, Fingerprint: confirmation.InputFingerprint,
		Confirmation: confirmation, ExpiresAt: s.now().UTC().Add(PreparationTTL),
	}
	s.records[record.Token] = record
	copy := *record
	return &copy, nil
}

func (s *preparationStore) consume(token, session, canonical, fingerprint string) (app.Confirmation, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	record := s.records[token]
	if record == nil {
		return app.Confirmation{}, errConfirmationReplayed
	}
	if record.Consumed {
		return app.Confirmation{}, errConfirmationReplayed
	}
	if !s.now().UTC().Before(record.ExpiresAt) {
		record.Consumed = true
		return app.Confirmation{}, errConfirmationExpired
	}
	if record.Session != session || record.Canonical != canonical {
		record.Consumed = true
		return app.Confirmation{}, errConfirmationMismatch
	}
	if record.Fingerprint != fingerprint {
		record.Consumed = true
		return app.Confirmation{}, errStaleConfirmation
	}
	record.Consumed = true
	return record.Confirmation, nil
}

func (s *preparationStore) reapLocked() {
	now := s.now().UTC()
	for token, record := range s.records {
		if !now.Before(record.ExpiresAt) {
			delete(s.records, token)
		}
	}
}

func confirmationDedupKey(session, token string) string {
	digest := sha256.Sum256([]byte(session + "\x00" + token))
	return hex.EncodeToString(digest[:])
}

var (
	errConfirmationExpired  = errors.New("confirmation expired")
	errConfirmationMismatch = errors.New("confirmation mismatch")
	errConfirmationReplayed = errors.New("confirmation replayed")
	errStaleConfirmation    = errors.New("stale confirmation")
)

package web

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

const (
	MaxActiveOperations        = 8
	MaxPreparations            = 128
	PreparationTTL             = 2 * time.Minute
	MaxEventsPerOperation      = 256
	MaxEventBytesPerOperation  = 256 * 1024
	MaxEncodedEventBytes       = 16 * 1024
	MaxTerminalResultBytes     = 256 * 1024
	MaxSubscribersPerOperation = 8
	MaxConcurrentStreams       = 32
	SubscriberQueueSize        = 32
	TerminalRetention          = 10 * time.Minute
	SSEHeartbeat               = 15 * time.Second
	MaxStreamLifetime          = 30 * time.Minute
)

var (
	errOperationCapacity  = errors.New("operation capacity reached")
	errSubscriberCapacity = errors.New("subscriber capacity reached")
	errServerDraining     = errors.New("server draining")
	errOperationNotFound  = errors.New("operation not found")
)

type operationDocument struct {
	ID            string              `json:"id"`
	Kind          app.OperationKind   `json:"kind"`
	State         string              `json:"state"`
	Reason        string              `json:"reason,omitempty"`
	CreatedAt     time.Time           `json:"created_at"`
	StartedAt     *time.Time          `json:"started_at,omitempty"`
	FinishedAt    *time.Time          `json:"finished_at,omitempty"`
	LastEventID   string              `json:"last_event_id"`
	DurableStatus durableStatusDTO    `json:"durable_status"`
	Result        *operationResultDTO `json:"result,omitempty"`
}

type activeOperationDTO struct {
	ID        string            `json:"id"`
	Kind      app.OperationKind `json:"kind"`
	State     string            `json:"state"`
	Project   string            `json:"project,omitempty"`
	Sprint    string            `json:"sprint,omitempty"`
	Study     string            `json:"study,omitempty"`
	StartedAt *time.Time        `json:"started_at,omitempty"`
}

type durableStatusDTO struct {
	Available   bool   `json:"available"`
	RefreshPath string `json:"refresh_path,omitempty"`
}

type operationResultDTO struct {
	State     string       `json:"state"`
	Subject   string       `json:"subject,omitempty"`
	Message   string       `json:"message,omitempty"`
	Content   string       `json:"content,omitempty"`
	Truncated bool         `json:"truncated,omitempty"`
	Findings  []findingDTO `json:"findings,omitempty"`
	Error     *errorBody   `json:"error,omitempty"`
}

type operationEvent struct {
	ID   uint64
	Name string
	Data []byte
}

type operationSubscriber struct {
	id uint64
	ch chan operationEvent
}

type operationRecord struct {
	doc         operationDocument
	session     string
	request     app.OperationRequest
	cancel      context.CancelFunc
	cancelOnce  sync.Once
	done        chan struct{}
	nextEventID uint64
	events      []operationEvent
	eventBytes  int
	subscribers map[uint64]*operationSubscriber
	nextSubID   uint64
	dedupKey    string
}

type operationHub struct {
	rootCtx context.Context
	ops     app.WebOperations
	now     func() time.Time
	id      func() string

	mu       sync.Mutex
	records  map[string]*operationRecord
	dedup    map[string]string
	active   int
	streams  int
	draining bool
	counters operationCounters
}

type operationCounters struct {
	starts             atomic.Int64
	active             atomic.Int64
	terminal           atomic.Int64
	capacityRejections atomic.Int64
	cancellations      atomic.Int64
	activeStreams      atomic.Int64
	slowSubscribers    atomic.Int64
	replayGaps         atomic.Int64
	projectionDrops    atomic.Int64
	shutdownCleanups   atomic.Int64
}

func newOperationHub(rootCtx context.Context, ops app.WebOperations, now func() time.Time, id func() string) *operationHub {
	if rootCtx == nil {
		rootCtx = context.Background()
	}
	if now == nil {
		now = time.Now
	}
	if id == nil {
		id = randomRequestID
	}
	return &operationHub{rootCtx: rootCtx, ops: ops, now: now, id: id, records: make(map[string]*operationRecord), dedup: make(map[string]string)}
}

func (h *operationHub) start(session string, prepared app.Confirmation) (operationDocument, error) {
	return h.startConfirmed(session, "", func() (app.Confirmation, error) { return prepared, nil })
}

func (h *operationHub) startConfirmed(session, dedupKey string, confirm func() (app.Confirmation, error)) (operationDocument, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	if id := h.dedup[dedupKey]; dedupKey != "" && id != "" {
		if record := h.records[id]; record != nil && record.session == session {
			return cloneOperationDocument(record.doc), nil
		}
		delete(h.dedup, dedupKey)
	}
	if h.draining {
		h.counters.capacityRejections.Add(1)
		return operationDocument{}, errServerDraining
	}
	if h.active >= MaxActiveOperations {
		h.counters.capacityRejections.Add(1)
		return operationDocument{}, errOperationCapacity
	}
	if h.ops == nil {
		return operationDocument{}, errors.New("operation capability unavailable")
	}
	prepared, err := confirm()
	if err != nil {
		return operationDocument{}, err
	}
	id := "op_" + h.id()
	for h.records[id] != nil {
		id = "op_" + h.id()
	}
	created := h.now().UTC()
	ctx, cancel := context.WithCancel(h.rootCtx)
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		accepted, acceptErr := manager.AcceptOperation(ctx, prepared, dedupKey)
		if acceptErr != nil {
			if !errors.Is(acceptErr, app.ErrWebUnavailable) {
				cancel()
				return operationDocument{}, acceptErr
			}
		} else {
			id = accepted.RunID
			if accepted.Context != nil {
				ctx = accepted.Context
			}
			if accepted.Existing {
				doc := operationDocument{ID: id, Kind: prepared.Request.Kind, State: accepted.Lifecycle, CreatedAt: created, DurableStatus: durableStatusDTO{Available: true, RefreshPath: "/runs/" + id}}
				cancel()
				return doc, nil
			}
		}
	}
	record := &operationRecord{
		doc: operationDocument{
			ID: id, Kind: prepared.Request.Kind, State: "accepted", CreatedAt: created,
			DurableStatus: durableStatusDTO{Available: prepared.DurableRefreshPath != "", RefreshPath: prepared.DurableRefreshPath},
		},
		session: session, request: prepared.Request, cancel: cancel, done: make(chan struct{}),
		subscribers: make(map[uint64]*operationSubscriber), dedupKey: dedupKey,
	}
	h.records[id] = record
	if dedupKey != "" {
		h.dedup[dedupKey] = id
	}
	h.active++
	h.counters.starts.Add(1)
	h.counters.active.Add(1)
	h.appendEventLocked(record, "snapshot", map[string]any{"state": "accepted"})
	doc := cloneOperationDocument(record.doc)
	go h.run(ctx, record)
	return doc, nil
}

func (h *operationHub) run(ctx context.Context, record *operationRecord) {
	started := h.now().UTC()
	h.mu.Lock()
	if record.doc.State == "accepted" {
		record.doc.State = "running"
		record.doc.StartedAt = &started
		h.appendEventLocked(record, "progress", map[string]any{"message": "operation started", "state": "running"})
	}
	h.mu.Unlock()

	result, runErr := h.ops.RunOperation(ctx, record.request, func(event app.OperationEvent) {
		h.publishAppEvent(record, event)
	})
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		finishCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		finishErr := manager.FinishOperation(finishCtx, record.doc.ID, result.State, runErr)
		cancel()
		if finishErr != nil && !errors.Is(finishErr, app.ErrWebUnavailable) {
			runErr = errors.Join(runErr, finishErr)
		}
	}
	h.finish(record, result, runErr)
}

func (h *operationHub) publishAppEvent(record *operationRecord, event app.OperationEvent) {
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		committed, err := manager.RecordOperationEvent(context.Background(), record.doc.ID, event)
		if err != nil && !errors.Is(err, app.ErrWebUnavailable) {
			record.cancel()
			return
		}
		if err == nil && !committed {
			return
		}
	}
	name := "progress"
	if event.State == app.OperationFailed {
		name = "warning"
	}
	payload := map[string]any{
		"state": string(event.State), "stage": safeWebText(event.Stage), "task": safeWebText(event.Task),
		"message": safeWebText(event.Message), "completed": event.Completed, "total": event.Total, "attempt": event.Attempt,
		"event_kind": safeWebText(event.EventKind), "event_type": safeWebText(event.EventType), "tool": safeWebText(event.Tool), "action": safeWebText(event.Action),
		"tool_call_id": safeWebText(event.ToolCallID), "tool_status": safeWebText(event.ToolStatus),
		"tool_arguments": event.ToolArguments, "tool_result": event.ToolResult, "tool_error": event.ToolError,
		"reason": safeWebText(event.Reason), "detail": safeWebText(event.Detail),
		"runtime_attempts": event.RuntimeAttempts, "turns": event.Turns, "turns_known": event.TurnsKnown,
		"tokens": event.Tokens, "tokens_known": event.TokensKnown, "duration": safeWebText(event.Duration),
		"provider": safeWebText(event.Provider), "model": safeWebText(event.Model), "harness": safeWebText(event.Harness), "cost": safeWebText(event.Cost), "runtime_events": event.RuntimeEvents,
	}
	h.mu.Lock()
	defer h.mu.Unlock()
	if terminalOperationState(record.doc.State) {
		return
	}
	h.appendEventLocked(record, name, payload)
}

func (h *operationHub) finish(record *operationRecord, result app.OperationResult, runErr error) {
	finished := h.now().UTC()
	h.mu.Lock()
	defer h.mu.Unlock()
	if terminalOperationState(record.doc.State) {
		return
	}
	state := "succeeded"
	switch {
	case errors.Is(runErr, context.Canceled), result.State == app.OperationCancelled:
		state = "cancelled"
	case runErr != nil, result.State == app.OperationFailed:
		state = "failed"
	case result.State == app.OperationPartial:
		state = "interrupted"
	}
	record.doc.State = state
	record.doc.FinishedAt = &finished
	record.doc.Result = projectOperationResult(result)
	h.appendEventLocked(record, "terminal", map[string]any{"state": state, "reason": record.doc.Reason, "result": record.doc.Result})
	h.active--
	h.counters.active.Add(-1)
	h.counters.terminal.Add(1)
	close(record.done)
	for id, subscriber := range record.subscribers {
		close(subscriber.ch)
		delete(record.subscribers, id)
		h.streams--
		h.counters.activeStreams.Add(-1)
	}
}

func (h *operationHub) status(session, id string) (operationDocument, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	record := h.records[id]
	if record == nil || record.session != session {
		return operationDocument{}, errOperationNotFound
	}
	return cloneOperationDocument(record.doc), nil
}

func (h *operationHub) activeOperations(session string) []activeOperationDTO {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	result := make([]activeOperationDTO, 0, h.active)
	for _, record := range h.records {
		if record.session != session || terminalOperationState(record.doc.State) {
			continue
		}
		result = append(result, activeOperationDTO{
			ID: record.doc.ID, Kind: record.doc.Kind, State: record.doc.State,
			Project: record.request.Project, Sprint: record.request.Sprint, Study: record.request.Study,
			StartedAt: record.doc.StartedAt,
		})
	}
	sort.Slice(result, func(i, j int) bool {
		left, right := result[i].StartedAt, result[j].StartedAt
		if left == nil || right == nil {
			return left != nil
		}
		return left.After(*right)
	})
	return result
}

func (h *operationHub) cancelOperation(session, id, reason string) (operationDocument, bool, error) {
	h.mu.Lock()
	record := h.records[id]
	if record == nil || (session != "" && record.session != session) {
		h.mu.Unlock()
		return operationDocument{}, false, errOperationNotFound
	}
	if terminalOperationState(record.doc.State) {
		doc := cloneOperationDocument(record.doc)
		h.mu.Unlock()
		return doc, false, nil
	}
	requested := false
	record.cancelOnce.Do(func() {
		requested = true
		record.doc.State = "cancelling"
		record.doc.Reason = canonicalCancelReason(reason)
		h.appendEventLocked(record, "cancel_requested", map[string]any{"reason": record.doc.Reason})
	})
	doc := cloneOperationDocument(record.doc)
	cancel := record.cancel
	h.mu.Unlock()
	if requested {
		h.counters.cancellations.Add(1)
		cancel()
	}
	return doc, requested, nil
}

func (h *operationHub) subscribe(session, id string, lastID uint64) ([]operationEvent, <-chan operationEvent, func(), error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	record := h.records[id]
	if record == nil || record.session != session {
		return nil, nil, nil, errOperationNotFound
	}
	if h.streams >= MaxConcurrentStreams || len(record.subscribers) >= MaxSubscribersPerOperation {
		h.counters.capacityRejections.Add(1)
		return nil, nil, nil, errSubscriberCapacity
	}
	if lastID > 0 && len(record.events) > 0 && lastID < record.events[0].ID-1 {
		h.counters.replayGaps.Add(1)
		h.appendEventLocked(record, "recovery_required", map[string]any{
			"oldest_retained_id": strconv.FormatUint(record.events[0].ID, 10),
			"newest_retained_id": strconv.FormatUint(record.nextEventID, 10),
			"refresh_path":       record.doc.DurableStatus.RefreshPath,
		})
		h.appendEventLocked(record, "snapshot", map[string]any{"state": record.doc.State, "reason": record.doc.Reason})
	}
	replay := make([]operationEvent, 0, len(record.events))
	for _, event := range record.events {
		if event.ID > lastID {
			replay = append(replay, event)
		}
	}
	record.nextSubID++
	sub := &operationSubscriber{id: record.nextSubID, ch: make(chan operationEvent, SubscriberQueueSize)}
	if terminalOperationState(record.doc.State) {
		close(sub.ch)
	} else {
		record.subscribers[sub.id] = sub
		h.streams++
		h.counters.activeStreams.Add(1)
	}
	var once sync.Once
	unsubscribe := func() {
		once.Do(func() {
			h.mu.Lock()
			defer h.mu.Unlock()
			if current, ok := record.subscribers[sub.id]; ok {
				delete(record.subscribers, sub.id)
				h.streams--
				h.counters.activeStreams.Add(-1)
				close(current.ch)
			}
		})
	}
	return replay, sub.ch, unsubscribe, nil
}

func (h *operationHub) appendEventLocked(record *operationRecord, name string, payload any) {
	name = stableOperationEventName(name)
	record.nextEventID++
	body := map[string]any{
		"operation_id": record.doc.ID,
		"time":         h.now().UTC().Format(time.RFC3339Nano),
		"sequence":     record.nextEventID,
		"payload":      payload,
	}
	data, err := json.Marshal(body)
	if err != nil {
		h.counters.projectionDrops.Add(1)
		return
	}
	if len(data) > MaxEncodedEventBytes {
		data, _ = json.Marshal(map[string]any{
			"operation_id": record.doc.ID, "time": h.now().UTC().Format(time.RFC3339Nano),
			"sequence": record.nextEventID, "payload": map[string]any{"message": "event projection exceeded the safe size limit"},
		})
		name = "warning"
	}
	event := operationEvent{ID: record.nextEventID, Name: name, Data: data}
	record.events = append(record.events, event)
	record.eventBytes += len(data)
	for len(record.events) > MaxEventsPerOperation || record.eventBytes > MaxEventBytesPerOperation {
		record.eventBytes -= len(record.events[0].Data)
		record.events = record.events[1:]
	}
	record.doc.LastEventID = strconv.FormatUint(event.ID, 10)
	for id, subscriber := range record.subscribers {
		select {
		case subscriber.ch <- event:
		default:
			close(subscriber.ch)
			delete(record.subscribers, id)
			h.streams--
			h.counters.activeStreams.Add(-1)
			h.counters.slowSubscribers.Add(1)
		}
	}
}

func stableOperationEventName(name string) string {
	switch name {
	case "snapshot", "progress", "warning", "finding", "artifact", "cancel_requested", "recovery_required", "terminal":
		return name
	default:
		return "progress"
	}
}

func (h *operationHub) drainAndWait(ctx context.Context) error {
	h.mu.Lock()
	h.draining = true
	var records []*operationRecord
	for _, record := range h.records {
		if !terminalOperationState(record.doc.State) {
			records = append(records, record)
		}
	}
	h.mu.Unlock()
	for _, record := range records {
		_, _, _ = h.cancelOperation("", record.doc.ID, "server_shutdown")
	}
	h.counters.shutdownCleanups.Add(int64(len(records)))
	for _, record := range records {
		select {
		case <-record.done:
		case <-ctx.Done():
			persistErr := h.persistCleanupUncertain(records)
			h.markCleanupUncertain(records)
			return errors.Join(ctx.Err(), persistErr)
		}
	}
	return nil
}

func (h *operationHub) persistCleanupUncertain(records []*operationRecord) error {
	recorder, ok := h.ops.(app.OperationCleanupRecorder)
	if !ok {
		return errors.New("operation capability cannot persist cleanup uncertainty")
	}
	var result error
	for _, record := range records {
		h.mu.Lock()
		terminal := terminalOperationState(record.doc.State)
		h.mu.Unlock()
		if terminal {
			continue
		}
		persistCtx, cancel := context.WithTimeout(context.Background(), time.Second)
		err := recorder.RecordOperationCleanupUncertain(persistCtx, app.OperationCleanupUncertain{
			OperationID: record.doc.ID,
			Request:     record.request,
			Reason:      "server_shutdown",
			RecordedAt:  h.now().UTC(),
		})
		cancel()
		if err != nil {
			result = errors.Join(result, fmt.Errorf("persist cleanup uncertainty for %s: %w", record.doc.ID, err))
		}
	}
	return result
}

func (h *operationHub) markCleanupUncertain(records []*operationRecord) {
	h.mu.Lock()
	defer h.mu.Unlock()
	finished := h.now().UTC()
	for _, record := range records {
		if terminalOperationState(record.doc.State) {
			continue
		}
		record.doc.State = "cleanup_uncertain"
		record.doc.Reason = "server_shutdown"
		record.doc.FinishedAt = &finished
		record.doc.Result = &operationResultDTO{State: "cleanup_uncertain", Message: "Cleanup did not finish before the shutdown deadline. Refresh durable status before retrying."}
		h.appendEventLocked(record, "terminal", map[string]any{"state": record.doc.State, "reason": record.doc.Reason})
		h.active--
		h.counters.active.Add(-1)
		h.counters.terminal.Add(1)
		close(record.done)
		for id, subscriber := range record.subscribers {
			close(subscriber.ch)
			delete(record.subscribers, id)
			h.streams--
			h.counters.activeStreams.Add(-1)
		}
	}
}

func (h *operationHub) isDraining() bool {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.draining
}

func (h *operationHub) reapLocked() {
	now := h.now().UTC()
	for id, record := range h.records {
		if record.doc.FinishedAt != nil && now.Sub(*record.doc.FinishedAt) >= TerminalRetention {
			delete(h.records, id)
			if record.dedupKey != "" {
				delete(h.dedup, record.dedupKey)
			}
		}
	}
}

func projectOperationResult(result app.OperationResult) *operationResultDTO {
	out := &operationResultDTO{
		State: safeWebText(string(result.State)), Subject: safeWebText(result.Subject), Message: safeWebText(result.Message),
		Content: safeProjectedText(result.Content, MaxTerminalResultBytes/2), Truncated: result.Truncated,
	}
	for _, finding := range result.Findings {
		out.Findings = append(out.Findings, findingDTO{
			Severity: safeWebText(finding.Severity), Section: safeWebText(finding.Section), Problem: safeWebText(finding.Problem),
			Cause: safeWebText(finding.Cause), Suggestion: safeWebText(finding.Suggestion),
		})
	}
	if result.Error != nil {
		out.Error = &errorBody{Code: safeWebText(result.Error.Code), Message: safeWebText(result.Error.Message), Retryable: result.Error.Retryable, Details: map[string]any{
			"category": safeWebText(result.Error.Category), "component": safeWebText(result.Error.Component), "cause": safeWebText(result.Error.Cause), "guidance": safeWebText(result.Error.Guidance),
		}}
	}
	if data, _ := json.Marshal(out); len(data) > MaxTerminalResultBytes {
		out.Content = ""
		out.Findings = nil
		out.Truncated = true
		out.Message = safeBoundedText(out.Message, 4096)
	}
	return out
}

func cloneOperationDocument(doc operationDocument) operationDocument {
	clone := doc
	if doc.Result != nil {
		result := *doc.Result
		result.Findings = append([]findingDTO(nil), doc.Result.Findings...)
		if doc.Result.Error != nil {
			err := *doc.Result.Error
			result.Error = &err
		}
		clone.Result = &result
	}
	return clone
}

func terminalOperationState(state string) bool {
	switch state {
	case "succeeded", "failed", "cancelled", "interrupted", "cleanup_uncertain":
		return true
	default:
		return false
	}
}

func canonicalCancelReason(reason string) string {
	switch reason {
	case "server_shutdown", "timeout", "recovery":
		return reason
	default:
		return "user_request"
	}
}

func safeWebText(value string) string {
	return safeProjectedText(value, 4096)
}

func safeProjectedText(value string, limit int) string {
	value = strings.TrimSpace(value)
	lower := strings.ToLower(value)
	for _, marker := range []string{"token=", "secret=", "authorization:", "cookie:"} {
		if index := strings.Index(lower, marker); index >= 0 {
			value = value[:index] + "[redacted]"
			lower = strings.ToLower(value)
		}
	}
	if strings.Contains(value, "/home/") || strings.Contains(value, `C:\\Users\\`) {
		value = "[redacted path]"
	}
	return safeBoundedText(value, limit)
}

func safeBoundedText(value string, limit int) string {
	if len(value) <= limit {
		return value
	}
	return value[:limit] + "…"
}

func parseEventID(value string) (uint64, error) {
	if strings.TrimSpace(value) == "" {
		return 0, nil
	}
	id, err := strconv.ParseUint(value, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid Last-Event-ID")
	}
	return id, nil
}

package runcontrol

import (
	"encoding/json"
	"path/filepath"
	"strings"
	"time"
)

var allowedEventPayloadFields = map[string]struct{}{
	"runtime_event_id": {}, "runtime_run_id": {}, "agentwrap_run_id": {}, "session_id": {},
	"external_harness_run_id": {}, "type": {}, "kind": {}, "state": {}, "status": {},
	"outcome": {}, "reason": {}, "category": {}, "code": {}, "count": {}, "known": {},
	"input_tokens": {}, "output_tokens": {}, "total_tokens": {}, "turns": {},
	"artifact_kind": {}, "artifact_id": {}, "lifecycle": {}, "liveness": {},
	"message": {}, "index": {}, "scope": {}, "tool": {}, "action": {}, "detail": {},
	"tool_call_id": {}, "tool_name": {}, "tool_status": {}, "tool_arguments": {},
	"tool_result": {}, "tool_error": {},
	"provider": {}, "model": {}, "harness": {},
	"phase_state": {}, "summary": {},
}

// sanitizeEventDraft is the final storage gate. Producers may only submit
// bounded product-owned fields; raw payloads, prompts, arbitrary diagnostics,
// credentials, and unrestricted paths are replaced with explicit omission.
func sanitizeEventDraft(input EventDraft) EventDraft {
	out := EventDraft{
		Type: input.Type, Scope: input.Scope, Stage: safeEventValue(input.Stage, MaxTargetFieldBytes),
		Task: safeEventValue(input.Task, MaxTargetFieldBytes), Kind: safeEventValue(input.Kind, MaxSafeValueBytes),
		Tool: safeEventValue(input.Tool, MaxSafeValueBytes), Action: safeEventValue(input.Action, MaxSafeValueBytes),
		Reason: safeEventValue(input.Reason, MaxSafeValueBytes), Detail: safeEventValue(input.Detail, MaxSafeValueBytes), Lifecycle: input.Lifecycle,
		Payload: make(map[string]string), Omission: cloneOmission(input.Omission),
	}
	omitted := uint64(0)
	for key, value := range input.Payload {
		if _, ok := allowedEventPayloadFields[key]; !ok || sensitiveEventField(key) || unsafeEventValue(value) {
			omitted++
			continue
		}
		if len(value) > MaxSafeValueBytes {
			omitted++
			continue
		}
		out.Payload[key] = safeEventValue(value, MaxSafeValueBytes)
	}
	if out.Stage != input.Stage || out.Task != input.Task {
		omitted++
	}
	if omitted > 0 {
		mergeOmission(&out, "unsafe event detail omitted", omitted, nil, nil)
	}
	encoded, err := json.Marshal(out)
	if err != nil || len(encoded) > MaxEncodedEventBytes {
		return EventDraft{
			Type:     EventWarning,
			Payload:  map[string]string{"code": "event_detail_oversize", "reason": "event detail exceeded durable limit"},
			Omission: &Omission{Reason: "oversize event detail omitted", Count: max(omitted, 1)},
		}
	}
	return out
}

func mergeOmission(draft *EventDraft, reason string, count uint64, first, last *time.Time) {
	if draft.Omission == nil {
		draft.Omission = &Omission{Reason: reason, Count: count, FirstAt: first, LastAt: last}
		return
	}
	draft.Omission.Count += count
	if draft.Omission.Reason == "" {
		draft.Omission.Reason = reason
	}
	if draft.Omission.FirstAt == nil {
		draft.Omission.FirstAt = first
	}
	if last != nil {
		draft.Omission.LastAt = last
	}
}

func sensitiveEventField(key string) bool {
	key = strings.ToLower(key)
	for _, fragment := range []string{"secret", "token", "credential", "password", "prompt", "payload", "stdout", "stderr", "path", "command"} {
		if strings.Contains(key, fragment) {
			return true
		}
	}
	return false
}

func unsafeEventValue(value string) bool {
	lower := strings.ToLower(strings.TrimSpace(value))
	if strings.ContainsAny(value, "\x00\r\n") || filepath.IsAbs(value) {
		return true
	}
	if len(value) >= 3 && value[1] == ':' && (value[2] == '\\' || value[2] == '/') {
		return true
	}
	for _, marker := range []string{"bearer ", "sk-", "ghp_", "github_pat_", "-----begin private key"} {
		if strings.Contains(lower, marker) {
			return true
		}
	}
	return false
}

func safeEventValue(value string, limit int) string {
	value = strings.Map(func(r rune) rune {
		if r == 0 || r == '\r' || r == '\n' {
			return -1
		}
		return r
	}, strings.TrimSpace(value))
	if len(value) > limit {
		value = value[:limit]
	}
	return value
}

