		t.Fatal("DEFENSE HOLDS: separate confirmations produce distinct digests")
	}

	repository, err := runcontrol.OpenSQLite(ctx, t.TempDir(), runcontrol.SQLiteOptions{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = repository.Close() })
	owner, err := currentRunOwner()
	if err != nil {
		t.Fatal(err)
	}
	manager := newDurableOperationManager(repository, owner)
	firstAccepted, err := manager.AcceptOperation(ctx, first, d1)
	if err != nil {
		t.Fatal(err)
	}
	if firstAccepted.Existing {
		t.Fatal("first acceptance must be fresh")
	}
	if err := manager.FinishOperation(context.Background(), firstAccepted.RunID, OperationComplete, nil); err != nil {
		t.Fatal(err)
	}
	secondAccepted, err := manager.AcceptOperation(ctx, second, d2)
	if err != nil {
		t.Fatalf("second independent confirmation rejected outright: %v", err)
	}
	t.Logf("second acceptance existing=%t runID=%s lifecycle=%q", secondAccepted.Existing, secondAccepted.RunID, secondAccepted.Lifecycle)
	if !secondAccepted.Existing {
		t.Fatal("DEFENSE HOLDS: second confirmation started a fresh run")
	}
	t.Errorf("CONFIRMED: an unrelated later confirmation of identical inputs dedupes into the finished run (Existing=%t lifecycle=%q)", secondAccepted.Existing, secondAccepted.Lifecycle)
}

func short(s string) string {
	if len(s) > 12 {
		return s[:12] + "..."
	}
	return s
}
